 boolean notaLive(){DesktopWindow nota=windows().get("@nota");return nota!=null&&nota.getParent()!=null;}
 View taskItem(String id){HorizontalScrollView strip=(HorizontalScrollView)root.findViewWithTag("taskbar-items");ViewGroup items=(ViewGroup)strip.getChildAt(0);for(int i=0;i<items.getChildCount();i++)if(id.equals(TaskbarReorder.key(items.getChildAt(i))))return items.getChildAt(i);return null;}
 void checkNotaIdle(String label){check(!fixedNota().isSelected()&&fixedNota().getContentDescription().toString().equals("Open Nth Nota"),"Closed Nota is idle: "+label);check(!backgroundDrawn(fixedNota()),"Closed Nota draws no running highlight: "+label);}
 boolean backgroundDrawn(View view){Bitmap bitmap=Bitmap.createBitmap(view.getWidth(),view.getHeight(),Bitmap.Config.ARGB_8888);view.getBackground().draw(new Canvas(bitmap));int[] pixels=new int[bitmap.getWidth()*bitmap.getHeight()];bitmap.getPixels(pixels,0,bitmap.getWidth(),0,0,bitmap.getWidth(),bitmap.getHeight());bitmap.recycle();for(int pixel:pixels)if(Color.alpha(pixel)!=0)return true;return false;}
