 void inject(long down,int action,float x,float y){MotionEvent event=MotionEvent.obtain(down,SystemClock.uptimeMillis(),action,x,y,0);event.setSource(InputDevice.SOURCE_TOUCHSCREEN);getUiAutomation().injectInputEvent(event,true);event.recycle();}
 View fixedNota(){View bar=TenSmoke.description(root,"Desktop taskbar");for(int i=0;i<((ViewGroup)bar).getChildCount();i++){View child=((ViewGroup)bar).getChildAt(i);if("@nota".equals(child.getTag(R.id.taskbar_order_key)))return child;}throw new AssertionError("Fixed Nota slot missing");}
 int countNota(View view){int n="@nota".equals(view.getTag(R.id.taskbar_order_key))?1:0;if(view instanceof ViewGroup)for(int i=0;i<((ViewGroup)view).getChildCount();i++)n+=countNota(((ViewGroup)view).getChildAt(i));return n;}
 boolean descendant(View root,View target){if(root==target)return true;if(root instanceof ViewGroup)for(int i=0;i<((ViewGroup)root).getChildCount();i++)if(descendant(((ViewGroup)root).getChildAt(i),target))return true;return false;}
 boolean hasItalic(View view){if(view instanceof TextView&&((((TextView)view).getTypeface().getStyle()&Typeface.ITALIC)!=0))return true;if(view instanceof ViewGroup)for(int i=0;i<((ViewGroup)view).getChildCount();i++)if(hasItalic(((ViewGroup)view).getChildAt(i)))return true;return false;}
